import assert from 'node:assert/strict';
import { readdirSync, statSync } from 'node:fs';
import { resolve } from 'node:path';
import { fileURLToPath } from 'node:url';

const repoRoot = resolve(fileURLToPath(new URL('..', import.meta.url)));
const assetsDirectory = resolve(repoRoot, 'dist', 'assets');
const assets = readdirSync(assetsDirectory)
  .filter((file) => file.endsWith('.js'))
  .map((file) => ({ file, bytes: statSync(resolve(assetsDirectory, file)).size }));
const findChunk = (prefix) => assets.find((asset) => asset.file.startsWith(prefix));

const entry = findChunk('index-');
const agentRuntime = findChunk('agent-runtime-');
const reactVendor = findChunk('react-vendor-');
const iconsVendor = findChunk('icons-vendor-');
const agentMarketRouteView = findChunk('AgentMarketRouteView-');
const agentDossierRouteView = findChunk('AgentDossierRouteView-');
const projectChatRouteView = findChunk('ProjectChatRouteView-');
const projectTimelineRouteView = findChunk('ProjectTimelineRouteView-');
const projectDashboardAdvancedView = findChunk('ProjectDashboardAdvancedView-');
const projectDashboardContentLayout = findChunk('ProjectDashboardContentLayout-');
const projectDashboardTopPanels = findChunk('ProjectDashboardTopPanels-');
const projectDashboardManagerBody = findChunk('ProjectDashboardManagerBody-');
const projectDashboardManagerCorePanels = findChunk('ProjectDashboardManagerCorePanels-');
const projectDashboardWorkLoopPanels = findChunk('ProjectDashboardWorkLoopPanels-');
const projectDashboardKickoffCollaborationPanels = findChunk('ProjectDashboardKickoffCollaborationPanels-');
const projectDashboardCollaborationOperationsPanels = findChunk('ProjectDashboardCollaborationOperationsPanels-');
const projectDashboardManagerProofRoutePanels = findChunk('ProjectDashboardManagerProofRoutePanels-');
const projectDashboardCoordinationTeamPanels = findChunk('ProjectDashboardCoordinationTeamPanels-');
const projectDashboardManagerCollaborationBody = findChunk('ProjectDashboardManagerCollaborationBody-');
const projectDashboardManagerReadyPackageSnapshot = findChunk('ProjectDashboardManagerReadyPackageSnapshot-');
const projectDashboardManagerReadyPackageCorePanels = findChunk('ProjectDashboardManagerReadyPackageCorePanels-');
const projectDashboardManagerReadyPackageOperationalPanels = findChunk('ProjectDashboardManagerReadyPackageOperationalPanels-');
const projectDashboardManagerBackendSnapshotPanels = findChunk('ProjectDashboardManagerBackendSnapshotPanels-');
const projectDashboardManagerBackendActivityPanels = findChunk('ProjectDashboardManagerBackendActivityPanels-');
const projectDashboardManagerBackendReadModelPanels = findChunk('ProjectDashboardManagerBackendReadModelPanels-');
const projectDashboardManagerWorkerStationPanels = findChunk('ProjectDashboardManagerWorkerStationPanels-');
const projectDashboardManagerBackendStationContent = findChunk('ProjectDashboardManagerBackendStationContent-');
const projectDashboardManagerBackendStationRegion = findChunk('ProjectDashboardManagerBackendStationRegion-');

assert.ok(entry, 'Production build must emit an application entry chunk.');
assert.ok(agentRuntime, 'Production build must isolate the Agent runtime from the application entry.');
assert.ok(reactVendor, 'Production build must isolate React vendor code for cache reuse.');
assert.ok(iconsVendor, 'Production build must isolate icon vendor code for cache reuse.');
assert.ok(agentMarketRouteView, 'Production build must emit the lazy Agent Market route chunk.');
assert.ok(agentDossierRouteView, 'Production build must emit the lazy Agent Dossier route chunk.');
assert.ok(projectChatRouteView, 'Production build must emit the lazy complete Group Chat route chunk.');
assert.ok(projectTimelineRouteView, 'Production build must emit the lazy complete Timeline route chunk.');
assert.ok(projectDashboardAdvancedView, 'Production build must emit the lazy complete Dashboard advanced-view chunk.');
assert.ok(projectDashboardContentLayout, 'Production build must emit the lazy complete Dashboard content-layout chunk.');
assert.ok(projectDashboardTopPanels, 'Production build must emit the lazy complete Dashboard top-panels chunk.');
assert.ok(projectDashboardManagerBody, 'Production build must emit the lazy complete Dashboard manager-body chunk.');
assert.ok(projectDashboardManagerCorePanels, 'Production build must emit the lazy complete Dashboard manager core-panels chunk.');
assert.ok(projectDashboardWorkLoopPanels, 'Production build must emit the lazy complete Dashboard work-loop panels chunk.');
assert.ok(projectDashboardKickoffCollaborationPanels, 'Production build must emit the lazy complete Dashboard kickoff-collaboration panels chunk.');
assert.ok(projectDashboardCollaborationOperationsPanels, 'Production build must emit the lazy complete Dashboard collaboration-operations panels chunk.');
assert.ok(projectDashboardManagerProofRoutePanels, 'Production build must emit the lazy complete Dashboard Manager Proof Map route-panels chunk.');
assert.ok(projectDashboardCoordinationTeamPanels, 'Production build must emit the lazy complete Dashboard coordination-team panels chunk.');
assert.ok(projectDashboardManagerCollaborationBody, 'Production build must emit the lazy complete Dashboard manager-collaboration body chunk.');
assert.ok(projectDashboardManagerReadyPackageSnapshot, 'Production build must emit the lazy complete Dashboard Manager Ready Package snapshot chunk.');
assert.ok(projectDashboardManagerReadyPackageCorePanels, 'Production build must emit the lazy complete Dashboard Manager Ready Package core-panels chunk.');
assert.ok(projectDashboardManagerReadyPackageOperationalPanels, 'Production build must emit the lazy complete Dashboard Manager Ready Package operational-panels chunk.');
assert.ok(projectDashboardManagerBackendSnapshotPanels, 'Production build must emit the lazy complete Dashboard Manager backend-snapshot panels chunk.');
assert.ok(projectDashboardManagerBackendActivityPanels, 'Production build must emit the lazy complete Dashboard Manager backend-activity panels chunk.');
assert.ok(projectDashboardManagerBackendReadModelPanels, 'Production build must emit the lazy complete Dashboard Manager backend read-model panels chunk.');
assert.ok(projectDashboardManagerWorkerStationPanels, 'Production build must emit the lazy complete Dashboard Manager worker-station panels chunk.');
assert.ok(projectDashboardManagerBackendStationContent, 'Production build must emit the lazy complete Dashboard Manager backend-station content chunk.');
assert.ok(projectDashboardManagerBackendStationRegion, 'Production build must emit the lazy complete Dashboard Manager backend-station region chunk.');
assert.ok(entry.bytes < 700_000, `Application entry (${entry.bytes} bytes) exceeds the 700 KB parsed-JavaScript budget.`);

console.log(`Frontend bundle budget passed: entry ${entry.bytes} bytes; agent runtime ${agentRuntime.bytes} bytes; Agent Market ${agentMarketRouteView.bytes} bytes; Agent Dossier ${agentDossierRouteView.bytes} bytes; Group Chat ${projectChatRouteView.bytes} bytes; Timeline ${projectTimelineRouteView.bytes} bytes; Dashboard advanced view ${projectDashboardAdvancedView.bytes} bytes; Dashboard content layout ${projectDashboardContentLayout.bytes} bytes; Dashboard top panels ${projectDashboardTopPanels.bytes} bytes; Dashboard manager body ${projectDashboardManagerBody.bytes} bytes; Dashboard manager core panels ${projectDashboardManagerCorePanels.bytes} bytes; Dashboard work-loop panels ${projectDashboardWorkLoopPanels.bytes} bytes; Dashboard kickoff collaboration panels ${projectDashboardKickoffCollaborationPanels.bytes} bytes; Dashboard collaboration operations panels ${projectDashboardCollaborationOperationsPanels.bytes} bytes; Dashboard Manager Proof Map route panels ${projectDashboardManagerProofRoutePanels.bytes} bytes; Dashboard coordination team panels ${projectDashboardCoordinationTeamPanels.bytes} bytes; Dashboard manager collaboration body ${projectDashboardManagerCollaborationBody.bytes} bytes; Dashboard Manager Ready Package snapshot ${projectDashboardManagerReadyPackageSnapshot.bytes} bytes; Dashboard Manager Ready Package core panels ${projectDashboardManagerReadyPackageCorePanels.bytes} bytes; Dashboard Manager Ready Package operational panels ${projectDashboardManagerReadyPackageOperationalPanels.bytes} bytes; Dashboard Manager backend snapshot panels ${projectDashboardManagerBackendSnapshotPanels.bytes} bytes; Dashboard Manager backend activity panels ${projectDashboardManagerBackendActivityPanels.bytes} bytes; Dashboard Manager backend read-model panels ${projectDashboardManagerBackendReadModelPanels.bytes} bytes; Dashboard Manager worker-station panels ${projectDashboardManagerWorkerStationPanels.bytes} bytes; Dashboard Manager backend-station content ${projectDashboardManagerBackendStationContent.bytes} bytes; Dashboard Manager backend-station region ${projectDashboardManagerBackendStationRegion.bytes} bytes; React ${reactVendor.bytes} bytes; icons ${iconsVendor.bytes} bytes.`);
